// run_id is threaded forward as a value, never re-derived (D14).
const p = $input.first().json.output ?? {};
return [{ json: {
  run_id:   $('Start run').first().json.run_id,
  question: $('When Executed by Another Workflow').first().json.question,
  anchor:   String(p.anchor_ingredient ?? '').trim() || 'brewing',
  style:    String(p.style_context ?? '').trim(),
  direction: String(p.direction ?? 'general'),
}}];

const base = $('Unpack parse').first().json;
const a = $('Step 2a · retrieve anchor').first().json.rows ?? [];
const b = $input.first().json.rows ?? [];

// Deduplicate by chunk_id, then relabel S1..Sn across BOTH retrievals. Each call
// numbers from S1 independently, so using their labels would collide.
const seen = new Map();
for (const r of [...a, ...b]) if (!seen.has(r.chunk_id)) seen.set(r.chunk_id, r);
const rows = [...seen.values()];

// ⚠️ NOT an error when the web arm has passages: a gap question can legitimately
// retrieve nothing from the library. The web block is assembled below, and
// `proceed` accounts for it.
const noLibrary = !rows.length;

const idmap = {};
const passages = rows.map((r, n) => {
  const label = `S${n + 1}`;
  idmap[r.chunk_id] = { label, doc_title: r.doc_title, page: r.page };
  return `[${label}] (chunk_id ${r.chunk_id}) ${r.doc_title} · ${r.heading}${r.page ? ` · p.${r.page}` : ''}\n${r.text}`;
}).join('\n\n');

// ⛔ Coverage gate. nlq.search_knowledge returns a pure RRF score — 1/(rrf_k + rank) —
// so it is a function of rank alone and says NOTHING about relevance: an unrelated
// chunk scores exactly what a perfect hit scores. Retrieval therefore always returns
// six passages, even for an anchor the corpus has never heard of, and the propose
// step will dutifully invent something adjacent from them.
// The only honest signal available is lexical: did anything we retrieved actually
// mention the thing that was asked about?
const needle = String(base.anchor ?? '').trim().toLowerCase();
const hay = rows.map(r => `${r.doc_title} ${r.heading} ${r.text}`).join(' ').toLowerCase();
const anchor_covered = needle.length > 2 && hay.includes(needle);

// A question names one anchor ingredient, but it usually sits in a style the corpus
// does cover. Gating on the anchor alone throws the covered half away: "vanilla and
// poppy seeds in a pastry stout" refused on "poppy seeds" (0 chunks) while "pastry
// stout" had 15. Proceed when either is covered — `propose` already returns an
// unsupported candidate with cites: [], which `compose` prints under "Not from your
// library". Refuse only when neither the anchor nor the style is in the corpus.
const style = String(base.style ?? '').trim().toLowerCase();
const style_covered = style.length > 2 && hay.includes(style);
// ⭐ Web passages, when nlq.corpus_vocabulary_gap fired on either retrieval. They
// are labelled [W..] and go into the SAME pack, because `propose` can only cite
// what it was shown: before this it was handed library passages only and answered
// an uncovered anchor from its own memory instead -- measured 2026-09-15 on
// "What hops go with Talus?", which produced four invented pairings under the
// "Not from your library" heading while the web arm's passages sat unused.
const webRows = [];
const webSeen = new Set();
for (const src of [$('Step 2a · retrieve anchor').first().json, $input.first().json]) {
  for (const w of (src.web ?? [])) {
    if (!w || webSeen.has(w.url)) continue;   // one passage per source
    webSeen.add(w.url);
    webRows.push(w);
  }
}

// ⛔ Keyed by LABEL, not chunk_id: a web passage has no chunk_id, and `Step 4 ·
// ground` resolves pack.idmap[key] first, so 'W1' lands here directly.
const webPassages = webRows.map((w, n) => {
  const label = `W${n + 1}`;
  idmap[label] = { label, doc_title: w.url, page: null, web: true };
  return `[${label}] (from the WEB, not the library) ${w.url}${w.heading ? ` · ${w.heading}` : ''}\n${w.text}`;
}).join('\n\n');

// ⛔ When the ANCHOR is uncovered, propose sees the web passages ONLY.
//
// Handing it both is what produced the worst answer this capability has given:
// asked "What hops go with Talus?" it read the handbook's `Hallertau Taurus`
// entry, decided Talus WAS Taurus -- "listed as an alternative for the Hallertau
// Taurus (Talus) variety" -- and returned Magnum, Hallertau Tradition and
// Herkules cited to [S1]. Confident, library-cited, and about a different hop.
// measured 2026-09-15, execution 1545.
//
// The library rows are here only because nlq.search_knowledge always returns
// p_limit rows; by definition none of them mentions the anchor, so for a question
// ABOUT the anchor they are the "adjacent filler" the coverage gate above exists
// to keep out. A gap fired, so the anchor is genuinely novel -- there is nothing
// to lose by dropping them and, measurably, invention to lose.
//
// ⚠️ Narrow on purpose: this only applies when webRows is non-empty, i.e. when a
// gap fired. The "vanilla and poppy seeds in a pastry stout" case -- uncovered
// anchor, covered style, no gap -- keeps its library passages exactly as before.
const allPassages = (webRows.length && !anchor_covered)
  ? webPassages
  : [passages, webPassages].filter(Boolean).join('\n\n');

// Web coverage is coverage: refusing while holding usable web passages is the one
// outcome worse than either answering or refusing cleanly.
const proceed = anchor_covered || style_covered || webRows.length > 0;

return [{ json: { ...base, passages: allPassages, idmap, anchor_covered,
                  style_covered, proceed, n_web: webRows.length,
                  chunk_ids: rows.map(r => r.chunk_id) } }];

