// The point of this capability: a candidate is either cited or labelled as a
// suggestion. Never silently mixed, and never carrying an invented chunk_id.
const pack = $('Build pack').first().json;
const cands = $input.first().json.output?.candidates ?? [];

// A 12B routinely cites the [S1] label it was shown instead of the chunk_id
// printed beside it. Both were in the passages, so both are real evidence —
// resolve chunk_id first, fall back to the label. Anything else is invented.
const byLabel = {};
for (const [cid, v] of Object.entries(pack.idmap)) byLabel[v.label] = v;

function resolve(c) {
  const key = String(c).trim().replace(/^\[|\]$/g, '');
  if (pack.idmap[key]) return pack.idmap[key].label;
  const asLabel = /^S/i.test(key) ? key.toUpperCase() : `S${key}`;
  return byLabel[asLabel] ? asLabel : null;
}

const grounded = [], suggested = [], web = [];

for (const c of cands) {
  const labels = [...new Set((c.cites ?? []).map(resolve).filter(Boolean))];

  const line = `${c.candidate} — ${c.why}`;
  if (!labels.length) { suggested.push(line); continue; }

  // ⛔ A candidate supported ONLY by [W..] is not library-backed and must never be
  // composed as though it were. One [S..] label is enough to call it grounded --
  // the library carried it -- but zero means the web carried it alone.
  const cited = `${line} ${labels.map(l => `[${l}]`).join('')}`;
  if (labels.some(l => !/^W/.test(l))) grounded.push(cited);
  else web.push(cited);
}

// Zero candidates is no longer an error: the propose prompt is explicitly allowed
// to return an empty list rather than pad. compose turns 'none'/'none' into a plain
// statement that the library does not cover it.
const sources = Object.values(pack.idmap)
  .filter(v => [...grounded, ...web].some(g => g.includes(`[${v.label}]`)))
  .map(v => `[${v.label}] ${v.doc_title}${v.page ? `, p.${v.page}` : ''}`)
  .join('\n');

return [{ json: {
  run_id: pack.run_id,
  question: pack.question,
  grounded:  grounded.length  ? grounded.join('\n')  : 'none',
  suggested: suggested.length ? suggested.join('\n') : 'none',
  web:       web.length       ? web.join('\n')       : 'none',
  sources,
  n_grounded: grounded.length,
  n_web: web.length,
  n_suggested: suggested.length,
}}];

// Only one branch of `Anchor covered?` ran, so ask which before reading it —
// $('node').first() on a node that never executed throws.
const src = $('Wrap answer').isExecuted
  ? $('Wrap answer').first().json
  : $('Not in library').first().json;

// One item, one key — the toolWorkflow node hands the last output to the model.
return [{ json: { response: String(src.answer ?? '').trim() } }];

// The corpus never mentions this anchor, so there is no GROUNDED answer to give
// and no candidate to build one from. Saying that and stopping is still the right
// move when nothing else is available — the alternative is the propose step
// manufacturing adjacent filler from six passages that happen to rank highest
// without being about anything relevant.
//
// ⭐ But "nothing in the library" is exactly the condition the web arm exists for.
// Step 2a retrieves in `rows` mode, so when nlq.corpus_vocabulary_gap fired it
// carries `web`. There is no LLM on this branch, so the passages are presented
// as themselves rather than written up: honest, deterministic, and it cannot
// hallucinate a pairing it did not read.
const p = $input.first().json;

let web = [];
try { web = $('Step 2a · retrieve anchor').first().json.web ?? []; } catch (e) { /* none */ }

if (!web.length) {
  return [{ json: {
    run_id: p.run_id,
    status: 'refused',
    spent:  JSON.stringify({ reason: 'anchor_not_in_corpus', anchor: p.anchor }),
    answer: `Your library has nothing on ${p.anchor}. I can't answer this from the books you've ingested, and I'm not going to answer it from my own memory.`,
  }}];
}

// ⛔ [W..], never [S..]: these carry none of the library's editorial vetting, and
// the whole citation scheme exists so the reader can tell the two apart.
const body = web.map((w, n) =>
  `[W${n + 1}] ${w.text}\n    ${w.url}`
).join('\n\n');

// status stays inside obs.runs' CHECK — a web-sourced answer is 'ok', not a
// refusal. The distinction lives in `spent`, which needs no schema change.
return [{ json: {
  run_id: p.run_id,
  status: 'ok',
  spent:  JSON.stringify({ reason: 'anchor_from_web', anchor: p.anchor, web: web.length }),
  answer: `Your library has nothing on ${p.anchor}, so this is from the web and not from your books — treat it accordingly.\n\n${body}`,
}}];

const g = $('Step 4 · ground').first().json;
return [{ json: {
  run_id: g.run_id,
  status: 'ok',
  spent:  JSON.stringify({ grounded: g.n_grounded, suggested: g.n_suggested }),
  answer: String($input.first().json.output ?? '').trim()
            || `${g.grounded}\n\nSources:\n${g.sources}`,
}}];
